DEL_FLAG = '0'

    AND ENTERPRISE_ID = #{queryVo.enterpriseId}


    AND ENTERPRISE_NAME LIKE '%' || #{queryVo.enterpriseName} || '%'


    AND STATISTICS_PERIOD >= #{queryVo.statisticsPeriodStart}


    AND STATISTICS_PERIOD <= #{queryVo.statisticsPeriodEnd}


    AND OPERATING_STATUS = #{queryVo.operatingStatus}


    AND DEVELOPMENT_TREND = #{queryVo.developmentTrend}


    AND DATA_STATUS = #{queryVo.dataStatus}


    AND RISK_LEVEL = #{queryVo.riskLevel}


    AND UPDATE_TIME >= #{queryVo.updateTimeStart}


    AND UPDATE_TIME <= #{queryVo.updateTimeEnd}

